// notifVerb returns the verb phrase that follows the actor name for a given notification type.
func notifVerb(t string) string {
	switch t {
	case "issue_comment":
		return "commented on issue"
	case "pr_comment":
		return "commented on PR"
	case "issue_closed":
		return "closed issue"
	case "issue_reopened":
		return "reopened issue"
	case "pr_merged":
		return "merged PR"
	case "pr_closed":
		return "closed PR"
	case "pr_opened":
		return "opened PR"
	default:
		return t
	}
}

